mapper.select:
SELECT
    query_text AS queryText,
    preference_intent AS preferenceIntent,
    original_intent AS originalIntent,
    updated_at AS updatedAt
FROM fin_ex_intent_preference_correction_t
WHERE tenant_id = #{tenantId}
  AND user_id = #{userId}
  AND intent_access_name = #{intentAccessName}
ORDER BY updated_at DESC, id DESC
LIMIT #{limit}
